const chapterNames:Record<number,string>={1:"A lehetőség ára",2:"A fogadások árnya",3:"A mérleg nyelve",4:"A fény ára",5:"A korona vizsgálata",6:"A Fekete Érme tengeri útja"};

function choiceDifficulty(ch:number, seq:number){ return 4 + ch*2 + Math.floor(seq/4); }
function applyChoiceMeta(blueprint:MainStoryBlueprint,q:QuestDefinition){
  q.choices=blueprint.choices.map((c,i)=>({...c,requirement:Math.max(c.requirement,choiceDifficulty(blueprint.chapter,blueprint.sequence)),gold:8+blueprint.chapter*8+i*5,xp:20+blueprint.chapter*12+blueprint.sequence*2}));
}

export function applyMainStory(base:QuestDefinition[]):QuestDefinition[]{
  const map=new Map(R.map(x=>[x.id,x]));
  return base.map(q=>{
    const b=map.get(q.id); if(!b) return q;
    const next={...q,summary:b.summary,story:b.story,objective:b.objective,giver:b.giver as any,chapter:b.chapter,sequence:b.sequence,region:b.region as any};
    next.requirements=b.requirements;
    next.rewards=b.rewards;
    next.dramaturgy={hook:b.hook,twist:b.twist,reveal:b.reveal,consequence:b.consequence,failForward:b.failForward};
    next.audit={
      functionHooks:[{npcId:b.giver as any,functionId:"story",role:"core",label:"A szerep saját funkciója",narrativeUse:b.story}],
      itemHooks:b.requirements.filter(r=>r.itemId).map(r=>({itemId:r.itemId!,role:r.consume?"material":"clue",narrativeUse:r.label} as any)),
      relationshipFocus:[b.giver as any],memoryTags:[`chapter:${b.chapter}`,`region:${b.region}`,`story:${b.id}`],
      playerExperience:`${b.summary} ${b.twist}`,
      consequenceThread:b.consequence,
      nextThread:`A(z) ${chapterNames[b.chapter]} következő állomása a ${b.sequence+1}. lépés.`
    };
    applyChoiceMeta(b,next);
    return next;
  });
}

export const MAIN_STORY_BLUEPRINT=R;
